import{_ as o,o as e,c as t,a2 as r}from"./chunks/framework.CZGNF-7T.js";const _=JSON.parse('{"title":"공람 및 PDF 출력","description":"","frontmatter":{},"headers":[],"relativePath":"approval/pdf-print.md","filePath":"approval/pdf-print.md","lastUpdated":1788259563000}'),l={name:"approval/pdf-print.md"};function i(d,a,n,s,c,p){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="공람-및-pdf-출력" tabindex="-1">공람 및 PDF 출력 <a class="header-anchor" href="#공람-및-pdf-출력" aria-label="Permalink to &quot;공람 및 PDF 출력&quot;">​</a></h1><p>전자결재 완료 문서의 공람(참조자 열람) 기능과 공식 보관용 PDF 생성/인쇄 기능을 안내합니다.</p><h2 id="_1-공람-참조자-열람-확인" tabindex="-1">1. 공람 (참조자 열람 확인) <a class="header-anchor" href="#_1-공람-참조자-열람-확인" aria-label="Permalink to &quot;1. 공람 (참조자 열람 확인)&quot;">​</a></h2><p>기안자가 문서 작성 시 참조자로 지정한 임직원은 결재가 완료된 후 문서를 열람하고 확인 처리할 수 있습니다.</p><ul><li><strong>공람 알림</strong>: 최종 승인 즉시 참조자들에게 <code>[결재 공람]</code> 푸시 및 웹 알림이 발송됩니다.</li><li><strong>열람 이력 기록</strong>: 참조자가 문서를 조회하면 열람 일시가 시스템에 안전하게 기록됩니다.</li></ul><h2 id="_2-공식-pdf-문서-렌더링-및-출력" tabindex="-1">2. 공식 PDF 문서 렌더링 및 출력 <a class="header-anchor" href="#_2-공식-pdf-문서-렌더링-및-출력" aria-label="Permalink to &quot;2. 공식 PDF 문서 렌더링 및 출력&quot;">​</a></h2><p>최종 승인된 문서는 사내 감사 및 대외 증빙 용도로 사용할 수 있는 표준 A4 규격의 전자 직인 PDF가 자동으로 생성됩니다.</p><h3 id="pdf-주요-구성-요소" tabindex="-1">PDF 주요 구성 요소 <a class="header-anchor" href="#pdf-주요-구성-요소" aria-label="Permalink to &quot;PDF 주요 구성 요소&quot;">​</a></h3><ol><li><strong>문서 번호 및 기본 헤더</strong>: 고유 채번 번호(예: <code>BIZ-2026-0001</code>), 기안 부서, 기안자, 기안 일자, 보안 등급.</li><li><strong>전자 결재란 (서명/도장)</strong>: <ul><li>기안자, 중간 결재자, 최종 결재자의 직위/직책 및 전자 서명 이미지 날인.</li><li>각 결재자의 승인 일시(<code>YYYY.MM.DD HH:MM</code>) 표기.</li><li>대결 처리된 경우 <code>[대결: OOO]</code> 명시.</li></ul></li><li><strong>표준 본문 서식</strong>: 17종 양식별로 정렬된 표, 지출 그리드, 합계 금액, 세부 내용.</li><li><strong>첨부파일 목록</strong>: 첨부된 증빙 서류 파일명 목록.</li><li><strong>위변조 방지 해시(Hash)</strong>: 상신 및 승인 시점의 본문 무결성을 입증하는 SHA-256 고유 해시값 각인.</li></ol><h2 id="_3-pdf-다운로드-및-인쇄-방법" tabindex="-1">3. PDF 다운로드 및 인쇄 방법 <a class="header-anchor" href="#_3-pdf-다운로드-및-인쇄-방법" aria-label="Permalink to &quot;3. PDF 다운로드 및 인쇄 방법&quot;">​</a></h2><ol><li><strong><code>결재 문서함</code></strong> 또는 **<code>기안 문서함</code>**에서 최종 승인된 문서를 선택합니다.</li><li>우측 상단의 <strong><code>[PDF 다운로드]</code></strong> 또는 <strong><code>[인쇄]</code></strong> 버튼을 클릭합니다.</li><li>표준 A4 규격으로 브라우저에서 바로 미리보거나 파일로 저장할 수 있습니다.</li></ol>',11)])])}const f=o(l,[["render",i]]);export{_ as __pageData,f as default};
